# Set-Codex-LOOP-Mode.ps1 - Activate / Deactivate / Restore / Status LOOP global mode
# Usage: .\launchers\Set-Codex-LOOP-Mode.ps1 -Mode Activate [-LoopRoot <path>] [-CodexHome <path>]
#
# Parameters:
#   -Mode        Required. One of: Activate, Deactivate, Status, Restore
#   -LoopRoot    Optional. Path to the codex-loop-open-source root directory.
#                Defaults to parent of this script directory (launchers parent).
#   -CodexHome   Optional. Override Codex home directory. Default: $USERPROFILE\.codex

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Activate', 'Deactivate', 'Status', 'Restore')]
    [string]$Mode,

    [string]$LoopRoot = '',
    [string]$CodexHome = ''
)

$ErrorActionPreference = 'Stop'

if (-not $LoopRoot) {
    $LoopRoot = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
}
$LoopRoot = [IO.Path]::GetFullPath($LoopRoot)

if (-not $CodexHome) {
    $CodexHome = Join-Path $env:USERPROFILE '.codex'
}

$tool = Join-Path $LoopRoot 'harness\global_desktop_mode.py'

if (-not (Test-Path -LiteralPath $tool -PathType Leaf)) {
    throw "global_desktop_mode.py not found at: $tool`nSet -LoopRoot to the codex-loop-open-source directory."
}

$venvPython = Join-Path $LoopRoot 'venv\Scripts\python.exe'
if (Test-Path -LiteralPath $venvPython -PathType Leaf) {
    $python = $venvPython; $pythonArgs = @()
} elseif (Get-Command py.exe -ErrorAction SilentlyContinue) {
    $python = (Get-Command py.exe).Source; $pythonArgs = @('-3')
} elseif (Get-Command python3 -ErrorAction SilentlyContinue) {
    $python = (Get-Command python3).Source; $pythonArgs = @()
} elseif (Get-Command python -ErrorAction SilentlyContinue) {
    $python = (Get-Command python).Source; $pythonArgs = @()
} else {
    throw 'Python 3.11+ is required but not found. Install from https://python.org'
}

$action = switch ($Mode) {
    'Activate'   { 'activate' }
    'Deactivate' { 'deactivate' }
    'Restore'    { 'restore' }
    default      { 'status' }
}

& $python @pythonArgs $tool $action --root $LoopRoot --codex-home $CodexHome
if ($LASTEXITCODE -ne 0) {
    throw "Codex LOOP global mode action failed (exit $LASTEXITCODE): $Mode"
}

switch ($Mode) {
    'Activate' {
        Write-Host 'LOOP mode active. Managed hooks, context payload, active agreement, and spawn gate are installed.'
        Write-Host 'Every newly started or resumed Desktop task inherits LOOP orchestration regardless of project directory.'
        Write-Host 'Restart Codex Desktop for the runtime canary to take effect.'
    }
    'Deactivate' {
        Write-Host 'LOOP mode is inactive. New or resumed Desktop tasks will not inherit LOOP orchestration.'
    }
    'Restore' {
        Write-Host 'Pre-install global AGENTS.md and hooks.json were restored from the verified backup.'
    }
}

    return data


def runtime_canary(root: Path, codex_home: Path, mode: dict[str, Any]) -> dict[str, Any]:
    """Find a post-activation root rollout outside the fixed control root."""
    try:
        activated = datetime.fromisoformat(
            str(mode["updated_at"]).replace("Z", "+00:00")
        ).timestamp()
    except (KeyError, TypeError, ValueError):
        return {"verified": False}
    sessions = codex_home / "sessions"
    if not sessions.exists():
        return {"verified": False}
    candidates = sorted(
        sessions.rglob("rollout-*.jsonl"),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    for path in candidates[:128]:
        try:
            if path.stat().st_mtime + 1 < activated:
                break
            with path.open(encoding="utf-8", errors="replace") as handle:
                first = json.loads(handle.readline())
                meta = first.get("payload") if first.get("type") == "session_meta" else {}
                if not isinstance(meta, dict) or meta.get("parent_thread_id"):
                    continue
                cwd = Path(str(meta.get("cwd") or "")).resolve()
                if cwd == root or root in cwd.parents:
                    continue
                handle.seek(0)
                text = handle.read(4 * 1024 * 1024).replace("\\\\", "\\")
        except (OSError, TypeError, ValueError):
            continue
        if all(token in text for token in (
            "Active Codex LOOP global mode",
            f"LOOP_CONTROL_ROOT={root}",
            "Mandatory LOOP model routing",
        )):
            return {
                "verified": True,
                "session_id": str(meta.get("id") or ""),
                "cwd": str(cwd),
                "rollout": str(path),
            }
    return {"verified": False}


def command_is_managed(hook: dict[str, Any]) -> bool:
    text = " ".join(str(hook.get(key, "")) for key in ("command", "commandWindows"))
    normalized = text.replace("/", "\\").casefold()
    return any(name.casefold() in normalized for name in MANAGED_SCRIPTS)


def strip_managed_hooks(doc: dict[str, Any]) -> dict[str, Any]:
    result = dict(doc) if isinstance(doc, dict) else {}
    hooks = result.get("hooks")
    if not isinstance(hooks, dict):
        hooks = {}
    cleaned: dict[str, list[dict[str, Any]]] = {}
    for event, groups in hooks.items():
        if not isinstance(groups, list):
            continue
        event_groups: list[dict[str, Any]] = []
        for group in groups:
            if not isinstance(group, dict):
                continue
            handlers = group.get("hooks")
            if not isinstance(handlers, list):
                event_groups.append(group)
                continue
            retained = [handler for handler in handlers
                        if not (isinstance(handler, dict) and command_is_managed(handler))]
            if retained:
                copy = dict(group)
                copy["hooks"] = retained
                event_groups.append(copy)
        if event_groups:
            cleaned[event] = event_groups
    result["hooks"] = cleaned
    return result


def merged_hooks(root: Path, codex_home: Path) -> dict[str, Any]:
    destination = read_json(codex_home / "hooks.json", {})
    if not isinstance(destination, dict):
        raise ValueError(f"global hooks file is not a JSON object: {codex_home / 'hooks.json'}")
    source = read_json(root / "config" / "global_hooks.json", None)
    if not isinstance(source, dict) or not isinstance(source.get("hooks"), dict):
        raise ValueError("managed global_hooks.json is invalid")
    merged = strip_managed_hooks(destination)
    hooks = merged.setdefault("hooks", {})
    for event, groups in source["hooks"].items():
        hooks.setdefault(event, []).extend(groups)
    managed_description = str(source.get("description") or "").strip()
    existing_description = str(merged.get("description") or "").strip()
    if existing_description and managed_description not in existing_description:
        merged["description"] = existing_description + " | " + managed_description
    elif existing_description:
        merged["description"] = existing_description
    else:
        merged["description"] = managed_description
    return merged


def ensure_backup(root: Path, codex_home: Path, install_state: Path) -> dict[str, Any]:
    existing = read_json(install_state, None)
    if isinstance(existing, dict) and existing.get("schema") == INSTALL_SCHEMA:
        # v1 installations created before managed hooks did not record
        # requirements.toml. Extend the immutable restore ledger before the
        # first managed write, preserving the exact current bytes if present.
        files = existing.setdefault("files", {})
        if "requirements.toml" not in files:
            source = codex_home / "requirements.toml"
            record: dict[str, Any] = {"existed": source.exists()}
            if source.exists():
                backup = Path(str(existing["backup_dir"])) / "requirements.toml"
                data = source.read_bytes()
                shutil.copy2(source, backup)
                record.update({"sha256": digest(data), "backup": str(backup)})
            files["requirements.toml"] = record
            atomic_write(install_state, json_bytes(existing))
        return existing
    # Microseconds plus PID prevent two first-time launchers in the same second
    # from selecting the same immutable backup directory.
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S-%f") + f"-{os.getpid()}"
    backup = root.parent / "backups" / "global-mode" / stamp
    backup.mkdir(parents=True, exist_ok=False)
    files: dict[str, dict[str, Any]] = {}
    for name in ("AGENTS.md", "hooks.json", "requirements.toml"):
        source = codex_home / name
        record: dict[str, Any] = {"existed": source.exists()}
        if source.exists():
            data = source.read_bytes()
            shutil.copy2(source, backup / name)
            record.update({"sha256": digest(data), "backup": str(backup / name)})
        files[name] = record
    doc = {
        "schema": INSTALL_SCHEMA,
        "installed_at": utc_now(),
        "control_root": str(root),
        "codex_home": str(codex_home),
        "backup_dir": str(backup),
        "files": files,
    }
    atomic_write(install_state, json_bytes(doc))
    return doc

#!/usr/bin/env python3
"""Conditional global LOOP hook dispatcher.

Codex Desktop is a single application surface whose tasks may use unrelated
working directories.  Project-local hooks therefore cannot define a Desktop
"LOOP edition".  This wrapper makes LOOP mode explicit and app-wide without
copying the F2 runtime into every target repository:

* a marker under ``<package-parent>/state/global-loop-mode.json`` selects mode;
* SessionStart/SubagentStart inject the complete LOOP instructions;
* lifecycle and policy hooks run against the fixed F2 control root;
* an absent, inactive, malformed, or mismatched marker is a safe no-op.

The wrapper is installed as a user/global hook.  Project-local F2 hooks remain
valid and continue to work independently.
"""
from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path
from typing import Any


SCHEMA = "codex-loop-global-mode/v1"
DEFAULT_ROOT = Path(__file__).resolve().parents[1]


def _resolved(path: Path) -> Path:
    return path.expanduser().resolve()


def marker_path(root: Path) -> Path:
    override = os.environ.get("CODEX_LOOP_MODE_MARKER")
    return _resolved(Path(override)) if override else root.parent / "state" / "global-loop-mode.json"


def load_active_marker(root: Path) -> dict[str, Any] | None:
    path = marker_path(root)
    try:
        doc = json.loads(path.read_text(encoding="utf-8-sig"))
    except FileNotFoundError:
        return None
    except (OSError, ValueError) as exc:
        sys.stderr.write(f"global_loop_mode: marker unreadable ({exc}); inactive\n")
        return None
    if not isinstance(doc, dict) or doc.get("schema") != SCHEMA or doc.get("active") is not True:
        return None
    try:
        selected = _resolved(Path(str(doc["control_root"])))
    except (KeyError, OSError, TypeError, ValueError):
        return None
    if selected != _resolved(root):
        sys.stderr.write(
            f"global_loop_mode: marker control_root={selected} does not match installed root={root}; inactive\n"
        )
        return None
    return doc


def instruction_text(root: Path) -> str:
    sources = (
        root / "config" / "global_working_agreement.md",
        root / "AGENTS.md",
    )
    blocks: list[str] = [
        "# Active Codex LOOP global mode",
        "",
        f"LOOP_CONTROL_ROOT={root}",
        "The current task workspace is the target workspace; it does not need to contain the LOOP runtime.",
        "All packets, lifecycle state, model routing, and observer state use LOOP_CONTROL_ROOT.",
        "These instructions apply to every target workspace while global LOOP mode is active.",
    ]
    for source in sources:
        blocks.extend(("", f"<!-- source: {source} -->", source.read_text(encoding="utf-8-sig").strip()))
    return "\n".join(blocks).strip() + "\n"

#!/usr/bin/env python3
"""Fail closed when a LOOP root attempts an ambiguous child birth.

The configured default child model is defence in depth, not authorization.
Every ordinary Desktop child must be born with an explicit LOOP role, Sonnet
4.6 model, ultra effort, and an independent context.
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any

from leaf_agent_spawn_gate import is_spawn_tool, session_is_child


APPROVED_MODEL = "weiwu/aws.claude-sonnet-4.6"
APPROVED_EFFORT = "ultra"
APPROVED_ROLES = frozenset({
    "worker", "verifier", "reviewer", "plan_expander", "duty_officer",
})


def deny(reason: str) -> dict[str, Any]:
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": "LOOP root spawn denied: " + reason,
    }}


def decision(payload: dict[str, Any], sessions: Path) -> dict[str, Any] | None:
    tool_name = str(payload.get("tool_name") or payload.get("tool") or payload.get("name") or "")
    if not is_spawn_tool(tool_name) or "spawn_agent" not in tool_name.casefold():
        return None
    session_id = payload.get("session_id") or payload.get("thread_id")
    if os.environ.get("LOOP_LEAF_AGENT", "").strip() == "1" or session_is_child(session_id, sessions):
        # The dedicated leaf gate owns this case and denies all descendants.
        return None
    arguments = payload.get("tool_input")
    if not isinstance(arguments, dict):
        return deny("tool_input is absent or malformed; ambiguous births fail closed")

    role = str(arguments.get("agent_type") or "").strip().casefold()
    if not role or role == "default":
        return deny("agent_type must be an explicit LOOP role; roleless/default is prohibited")
    if role not in APPROVED_ROLES:
        return deny(f"agent_type={role!r} is not an approved LOOP child role")

    model = str(arguments.get("model") or "").strip()
    if model != APPROVED_MODEL:
        return deny(f"model must be explicitly pinned to {APPROVED_MODEL}")

    effort = str(arguments.get("reasoning_effort") or "").strip().casefold()
    if effort != APPROVED_EFFORT:
        return deny(f"reasoning_effort must be explicitly pinned to {APPROVED_EFFORT}")

    if arguments.get("fork_context") is True:
        return deny("fork_context=true is prohibited; LOOP children use independent context")
    return None


def main() -> int:
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    sessions = Path(os.environ.get(
        "CODEX_SESSIONS_DIR",
        str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
    )).resolve()
    result = decision(payload if isinstance(payload, dict) else {}, sessions)
    if result is not None:
        print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Deny recursive subagent births while leaving root-agent dispatch untouched.

The global throughput agreement authorizes roots to fill the shared LOOP
capacity.  A worker/verifier/reviewer is a leaf: allowing every leaf to apply
the same agreement recursively creates a 16x16 birth cascade.  This hook uses
the immutable rollout session_meta parent_thread_id as the authority.  It
does not cap root concurrency and does not terminate existing work.
"""
from __future__ import annotations

import json
import os
import sys
from pathlib import Path
from typing import Any


SPAWN_NAMES = ("spawn_agent", "create_thread", "fork_thread")


def is_spawn_tool(name: Any) -> bool:
    value = str(name or "").casefold()
    return any(item in value for item in SPAWN_NAMES)


def session_is_child(session_id: Any, sessions: Path) -> bool:
    value = str(session_id or "").strip()
    if not value or not sessions.exists():
        return False
    matches = sorted(sessions.rglob("rollout-*%s*.jsonl" % value),
                     key=lambda path: path.stat().st_mtime, reverse=True)
    for path in matches:
        try:
            with path.open(encoding="utf-8", errors="replace") as handle:
                for line in handle:
                    try:
                        row = json.loads(line)
                    except ValueError:
                        continue
                    if row.get("type") != "session_meta":
                        continue
                    payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
                    parent = payload.get("parent_thread_id")
                    if not parent:
                        source = payload.get("source") if isinstance(payload.get("source"), dict) else {}
                        subagent = source.get("subagent") if isinstance(source.get("subagent"), dict) else {}
                        spawn = subagent.get("thread_spawn") if isinstance(subagent.get("thread_spawn"), dict) else {}
                        parent = spawn.get("parent_thread_id") or spawn.get("parent_session_id")
                    return bool(parent)
        except OSError:
            continue
    return False


def decision(payload: dict[str, Any], sessions: Path) -> dict[str, Any] | None:
    if not is_spawn_tool(payload.get("tool_name") or payload.get("tool") or payload.get("name")):
        return None
    session_id = payload.get("session_id") or payload.get("thread_id")
    marked_leaf = os.environ.get("LOOP_LEAF_AGENT", "").strip() == "1"
    if not marked_leaf and not session_is_child(session_id, sessions):
        return None
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason": (
            "LOOP leaf agents cannot recursively spawn agents. Return the bounded "
            "result to the root orchestrator; the root owns shared global-60 refill."
        ),
    }}


def main() -> int:
    try:
        payload = json.loads(sys.stdin.read() or "{}")
    except ValueError:
        payload = {}
    sessions = Path(os.environ.get(
        "CODEX_SESSIONS_DIR",
        str(Path(os.environ.get("CODEX_HOME", str(Path.home() / ".codex"))) / "sessions"),
    )).resolve()
    result = decision(payload if isinstance(payload, dict) else {}, sessions)
    if result is not None:
        print(json.dumps(result, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
